function sAssert(bool $v,string $m):void{global $checks;$checks++;if(!$v)throw new RuntimeException($m);}
function sRows(string $q,array $a=[]):array{global $pdo;$s=$pdo->prepare($q);$s->execute($a);return $s->fetchAll(PDO::FETCH_ASSOC);}
function sVal(string $q,array $a=[]):mixed{$r=sRows($q,$a);return $r?reset($r[0]):null;}
