function sFlat(array $d,string $p=''):array{$r=[];foreach($d as $k=>$v){$n=$p===''?(string)$k:$p.'['.$k.']';if(is_array($v))$r+=sFlat($v,$n);else $r[$n]=$v;}return $r;}
function sCurl(string $who,string $path,?array $data=null){global $base,$cookies;$c=curl_init($base.'/'.$path);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_COOKIEFILE=>$cookies[$who],CURLOPT_COOKIEJAR=>$cookies[$who],CURLOPT_TIMEOUT=>30]);if($data!==null)curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>sFlat($data)]);return $c;}
function sHttp(string $who,string $path,?array $data=null):array{$c=sCurl($who,$path,$data);$raw=curl_exec($c);if(!is_string($raw))throw new RuntimeException(curl_error($c));$n=(int)curl_getinfo($c,CURLINFO_HEADER_SIZE);$status=(int)curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);$body=substr($raw,$n);if($status>=500||preg_match('/<b>(Warning|Fatal error|Notice)<\/b>:/i',$body))throw new RuntimeException('HTTP error '.$status.' '.$path.' '.substr(strip_tags($body),0,200));return ['status'=>$status,'body'=>$body];}
$mark='R3-'.strtoupper(bin2hex(random_bytes(6)));$password=$mark.'!Secure';
$legacyBefore=sRows('SELECT * FROM resource_requests ORDER BY request_id');$historicalItems=sRows('SELECT * FROM request_items ORDER BY request_item_id');$settings=sRows("SELECT * FROM system_settings WHERE setting_key IN ('facility_operating_start','facility_operating_end') ORDER BY setting_key");
try{
