    $resource=function(string $name,string $type='Item',string $mode='Aggregate')use($pdo,$mark,&$resources):int{sExec("INSERT INTO resources(resource_name,resource_type,tracking_mode,total_stock,available_stock,status,condition_status)VALUES(?,?,?,20,20,'Available','Good')",[$mark.' '.$name,$type,$mode]);return $resources[]=(int)$pdo->lastInsertId();};
    $hall=$resource('Hall','Facility','Facility');$otherHall=$resource('Other Hall','Facility','Facility');$item=$resource('Equipment');$paper=$resource('Paper','Item','Consumable');$png=gsoTestLetterImage();$day=date('Y-m-d',strtotime('+150 days'));
    $submit=function(string $who,int $primary,string $date,string $start='09:00',string $end='11:00',?string $period='AM',array $extras=[],bool $extended=false,bool $letter=true)use(&$csrf,$png):array{$d=['csrf_token'=>$csrf[$who],'quantity'=>1,'contact_number'=>'09123456789','date_needed'=>$date,'start_time'=>$start,'end_time'=>$end];if($period!==null)$d['facility_slot']=$period;if($extended)$d['request_extended_hours']='1';if($letter)$d['request_letter']=new CURLFile($png,'image/png','signed-letter.png');foreach($extras as $i=>$id)$d['extra_lines'][$i]=['resource_id'=>$id,'quantity'=>1];return sHttp($who,'borrower/request_resource.php?resource_id='.$primary,$d);};
    $newest=fn(string $who)=>(int)sVal('SELECT MAX(request_id) FROM resource_requests WHERE borrower_id=?',[$users[$who]]);
    $status=fn(int $id)=>sVal('SELECT status FROM resource_requests WHERE request_id=?',[$id]);
