    $make=function(string $who,int $facility,string $date,string $start,string $end,string $period,bool $verify=true)use($submit,$newest,&$requests,$pdo,$users):int{$submit($who,$facility,$date,$start,$end,$period);$id=$newest($who);$requests[]=$id;if($verify)gsoTestVerifiedLetter($pdo,$id,$users['admin']);return $id;};
    $count=(int)sVal('SELECT COUNT(*) FROM resource_requests');
