    foreach([[$hall,'07:00','09:00','AM',false],[$hall,'17:00','20:00','PM',false],[$item,'09:00','11:00','AM',false],[$paper,'09:00','11:00','PM',false]] as [$primary,$start,$end,$period,$extension]){$submit('a',$primary,$day,$start,$end,$period,[],$extension);sAssert((int)sVal('SELECT COUNT(*) FROM resource_requests')===$count,'Invalid normal-hours/non-facility period accepted');}
    foreach([$item,$paper] as $primary){$submit('a',$primary,$day,'09:00','11:00',null,[],false,false);$id=$newest('a');$requests[]=$id;sAssert((int)sVal('SELECT COUNT(*) FROM request_items WHERE request_id=? AND facility_slot IS NOT NULL',[$id])===0,'Non-facility stored a period');}
    $beforeStock=sRows('SELECT resource_id,total_stock,available_stock,under_repair_stock FROM resources ORDER BY resource_id');
