    $competing=$make('b',$hall,$day,'09:00','10:00','AM');sAssert($competing!==$first&&$status($competing)==='Pending','Pending overlap did not coexist');
    $sameOwner=$make('a',$hall,$day,'08:30','09:15','AM');sAssert($sameOwner!==$first&&$status($sameOwner)==='Pending','Owner-specific duplicate check incorrectly reserved a pending facility interval');
