    $crossNoon=$make('a',$hall,$day,'11:30','13:00','AM');$noon=$make('b',$hall,$day,'12:00','13:00','PM');sAssert($noon!==$pm2&&$status($noon)==='Pending','Cross-period pending request did not coexist');
    $approve('admin',$crossNoon);sAssert($status($crossNoon)==='Approved','AM start with end after noon was incorrectly treated as a fixed block');
    $approve('staff',$noon);sAssert($status($noon)==='Pending','Cross-period exact overlap was not blocked');
    $different=$make('b',$otherHall,$day,'08:00','09:30','AM');$approve('staff',$different);sAssert($status($different)==='Approved','Different facility incorrectly conflicted');
    sAssert(sRows('SELECT resource_id,total_stock,available_stock,under_repair_stock FROM resources ORDER BY resource_id')===$beforeStock,'Schedule creation changed stock');
    $r=gsoFetchRequestableResource($pdo,$hall);
    foreach(['Approved','Released','Return'] as $state){sExec('UPDATE resource_requests SET status=? WHERE request_id=?',[$state,$first]);sAssert(!checkResourceAvailability($pdo,$r,1,$day,'08:30','09:15',null)['ok'],'Confirmed state did not block '.$state);}
    foreach(['Rejected','Cancelled','Returned','Completed','Pending','Under Review'] as $state){sExec('UPDATE resource_requests SET status=? WHERE request_id=?',[$state,$first]);sAssert(checkResourceAvailability($pdo,$r,1,$day,'08:00','08:45',null)['ok'],'Closed/unconfirmed state blocked '.$state);}sExec("UPDATE resource_requests SET status='Approved' WHERE request_id=?",[$first]);
    $eveningDate=date('Y-m-d',strtotime('+151 days'));$response=$submit('a',$hall,$eveningDate,'17:00','20:00','PM',[],true);$evening=$newest('a');$requests[]=$evening;
    sAssert(str_contains($response['body'],'outside normal hours')&&$status($evening)==='Pending','Extended schedule silently accepted without review notice');gsoTestVerifiedLetter($pdo,$evening,$users['admin']);
    $approve('admin',$evening);sAssert($status($evening)==='Pending','Extended schedule approved without explicit authorization');$approve('admin',$evening,['allow_extended_hours'=>'1']);sAssert($status($evening)==='Pending','Extended schedule approved without audit remarks');
    foreach(['mis','director'] as $who){$approve($who,$evening,['allow_extended_hours'=>'1','extended_hours_remarks'=>'Not authorized']);sAssert($status($evening)==='Pending','Unauthorized role granted extended hours');}
    $approve('admin',$evening,['allow_extended_hours'=>'1','extended_hours_remarks'=>str_repeat('x',121)]);sAssert($status($evening)==='Pending','Overlong extended-hours remarks were accepted without safe audit storage');
    $approve('admin',$evening,['allow_extended_hours'=>'1','extended_hours_remarks'=>'GSO confirmed authorized campus evening event']);sAssert($status($evening)==='Approved','Explicit GSO evening exception failed');sAssert((int)sVal("SELECT COUNT(*) FROM activity_logs WHERE user_id=? AND action='Extended Facility Hours Authorized' AND details LIKE ?",[$users['admin'],'%Request #'.$evening.';%'])===1,'Evening exception missing audit record');
    // Config changes are authoritative and never overwritten by runtime initialization.
    sExec("UPDATE system_settings SET setting_value='09:00' WHERE setting_key='facility_operating_start'");sExec("UPDATE system_settings SET setting_value='16:00' WHERE setting_key='facility_operating_end'");
    $migrationRerun=shell_exec(escapeshellarg(PHP_BINARY).' '.escapeshellarg(dirname(__DIR__).'/scripts/migrate.php').' 2>&1');sAssert(is_string($migrationRerun)&&str_contains($migrationRerun,'Migrations completed')&&gsoFacilityOperatingHours($pdo)===['start'=>'09:00:00','end'=>'16:00:00'],'Runtime migration overwrote configured operating hours');
    $count=(int)sVal('SELECT COUNT(*) FROM resource_requests');$submit('a',$hall,date('Y-m-d',strtotime('+152 days')),'08:00','09:30','AM');sAssert((int)sVal('SELECT COUNT(*) FROM resource_requests')===$count,'Configured opening time ignored');$submit('a',$hall,date('Y-m-d',strtotime('+152 days')),'15:00','16:30','PM');sAssert((int)sVal('SELECT COUNT(*) FROM resource_requests')===$count,'Configured closing time ignored');
    foreach($settings as $setting)sExec('UPDATE system_settings SET setting_value=?,updated_at=? WHERE setting_key=?',[$setting['setting_value'],$setting['updated_at'],$setting['setting_key']]);
    // Facility slot is nullable for legacy lines but forbidden on equipment/consumables.
    foreach([$item,$paper] as $resourceId){$bad=false;try{sExec("UPDATE request_items SET facility_slot='AM' WHERE resource_id=?",[$resourceId]);}catch(Throwable $e){$bad=true;}sAssert($bad,'DB allowed period on non-facility line');}
    // Maintenance without period scope blocks both clock-semantic groups.
    $maintenanceDate=date('Y-m-d',strtotime('+153 days'));sExec("INSERT INTO maintenance_schedules(resource_id,start_date,end_date,reason,status,created_by)VALUES(?,?,?,'R3 whole day maintenance','Scheduled',?)",[$hall,$maintenanceDate,$maintenanceDate,$users['admin']]);$maintenance[]=(int)$pdo->lastInsertId();
    foreach([['09:00','10:00'],['13:00','14:00']] as [$a,$b])sAssert(!checkResourceAvailability($pdo,$r,1,$maintenanceDate,$a,$b,null)['ok'],'Maintenance did not block both periods');
    // Two independent operator sessions POST overlapping approvals concurrently.
    $raceDate=date('Y-m-d',strtotime('+154 days'));$raceA=$make('a',$hall,$raceDate,'09:00','11:00','AM');$raceB=$make('b',$hall,$raceDate,'10:00','11:30','AM');
    $multi=curl_multi_init();$handles=[];foreach([['admin',$raceA],['staff',$raceB]] as [$who,$id]){$c=sCurl($who,'admin/requests.php',['csrf_token'=>$csrf[$who],'request_id'=>$id,'action'=>'approve']);curl_multi_add_handle($multi,$c);$handles[]=$c;}
    do{$code=curl_multi_exec($multi,$running);if($running)curl_multi_select($multi,1);}while($running&&$code===CURLM_OK);
    foreach($handles as $c){sAssert((int)curl_getinfo($c,CURLINFO_RESPONSE_CODE)===302,'Concurrent approval did not fail/succeed cleanly');curl_multi_remove_handle($multi,$c);curl_close($c);}curl_multi_close($multi);
    sAssert((int)sVal("SELECT COUNT(*) FROM resource_requests WHERE request_id IN (?,?) AND status='Approved'",[$raceA,$raceB])===1,'Concurrent conflicting approvals both succeeded');
    // Mixed request uses one exact shared interval and one Facility-line period.
    $mixedDate=date('Y-m-d',strtotime('+155 days'));$submit('a',$item,$mixedDate,'13:00','15:30','PM',[$otherHall,$paper]);$mixed=$newest('a');$requests[]=$mixed;
    sAssert((int)sVal('SELECT COUNT(*) FROM request_items WHERE request_id=?',[$mixed])===3&&(int)sVal("SELECT COUNT(*) FROM request_items WHERE request_id=? AND facility_slot='PM' AND line_kind='Facility'",[$mixed])===1,'Mixed period not stored on one facility line');sAssert((int)sVal("SELECT COUNT(*) FROM request_items WHERE request_id=? AND line_kind<>'Facility' AND facility_slot IS NOT NULL",[$mixed])===0,'Mixed period duplicated on equipment');
    sAssert(calculateReservedItemQuantity($pdo,$item,$mixedDate,'13:30','14:00',null)>=1&&calculateReservedItemQuantity($pdo,$item,$mixedDate,'16:00','16:30',null)===0,'Mixed equipment availability did not use actual interval');gsoTestVerifiedLetter($pdo,$mixed,$users['admin']);$approve('admin',$mixed);
    sHttp('staff','admin/requests.php',['csrf_token'=>$csrf['staff'],'request_id'=>$mixed,'action'=>'release']);sAssert($status($mixed)==='Released'&&sVal('SELECT due_date FROM resource_requests WHERE request_id=?',[$mixed])===$mixedDate.' 15:30:00','Mixed release lost facility end-time deadline');
