    echo "PASS: R3 AM/PM classification and exact scheduling E2E ({$checks} checks).\n";
}catch(Throwable $e){$failed=$e;fwrite(STDERR,'FAIL: '.$e->getMessage()."\n".$e->getTraceAsString()."\n");}
finally{
    if($pdo->inTransaction())$pdo->rollBack();foreach($settings as $s)sExec('UPDATE system_settings SET setting_value=?,updated_at=? WHERE setting_key=?',[$s['setting_value'],$s['updated_at'],$s['setting_key']]);foreach($maintenance as $id)sExec('DELETE FROM maintenance_schedules WHERE maintenance_id=?',[$id]);
